<?php
declare(strict_types=1);
require dirname(__DIR__).'/src/bootstrap.php';
use SimpleStore\Notification\{NtfySettings as S,NtfyMessage as M,NtfyClient as C};
$check=static function(bool $ok,string $message):void { if(!$ok)throw new RuntimeException($message); };
$reject=static function(callable $f):void { try{$f();}catch(InvalidArgumentException $e){return;}throw new RuntimeException('Invalid input accepted'); };
$settings=S::portable(S::DEFAULTS);S::validate($settings);
$check(!$settings['enabled'] && $settings['topic']==='' && $settings['token']==='','Fresh install must not send anything');
$check(S::topicFromAddress(' https://ntfy.sh/private-fixture_12/ ')==='private-fixture_12','Full topic URL not accepted');
foreach(['http://ntfy.sh/topic','https://ntfy.sh.evil.test/topic','https://ntfy.sh@evil.test/topic','https://ntfy.sh/topic?token=x','https://ntfy.sh/topic/sub','https://127.0.0.1/topic','https://ntfy.sh/topic#secret',"https://ntfy.sh/topic\r\nInjected: x",'https://ntfy.sh/'.str_repeat('a',65)] as $url)$reject(fn()=>S::topicFromAddress($url));
foreach([['enabled'=>true],['priority'=>0],['priority'=>'3'],['token'=>"x\nHeader: x"],['topic'=>'a/b'],['include_contact'=>'yes']] as $bad)$reject(fn()=>S::validate(array_replace($settings,$bad)));
$settings['topic']='private-fixture';
$order=['id'=>42,'order_number'=>'DB-26-123','order_token'=>'DO-NOT-PUBLISH','created_at'=>'2026-11-06 12:30:00','total_czk'=>2100,'shipping_czk'=>100,'payment_method'=>'bank_transfer','payment_status'=>'pending','customer_email'=>'fixture@example.test','shipping'=>['recipient'=>'Žaneta Nová','phone'=>'+420123456789','label'=>'Doručení domů'],'items'=>[['name'=>'Červený batoh','quantity'=>2,'unit_price_czk'=>1000,'options'=>['Velikost'=>'M']]]];
$payload=M::order($order,$settings,'https://example.test/shop');
foreach(['6. 11. 2026 13:30','Žaneta Nová','2× Červený batoh (Velikost: M)','2 100 Kč','100 Kč'] as $part)$check(str_contains($payload['message'],$part),'Missing order detail: '.$part);
$check($payload['click']==='https://example.test/shop/admin/orders/?id=42','Admin URL must respect installation subdirectory');
$encoded=json_encode($payload,JSON_THROW_ON_ERROR);
$check(!str_contains($encoded,'DO-NOT-PUBLISH') && !str_contains($encoded,'fixture@example.test') && !str_contains($encoded,'123456789'),'Private fields leaked');
$settings['include_contact']=true;$payload=M::order($order,$settings,'http://localhost/shop');
$check(str_contains($payload['message'],'fixture@example.test') && !isset($payload['click']),'Optional contact or HTTPS-only admin link');
$order['items']=array_fill(0,40,['name'=>str_repeat('Žluťoučký ',100),'quantity'=>2,'unit_price_czk'=>1,'options'=>[]]);
$message=M::order($order,$settings,'')['message'];
$check(strlen($message)<=3500 && preg_match('//u',$message)===1 && str_contains($message,'Celý seznam'),'UTF-8 length/truncation');
$check(C::result(true,200,'{"id":"abc","event":"message"}')['state']==='sent','Valid confirmation');
foreach([[false,0,''],[true,200,'bad'],[true,200,'{}']] as $result)$check(C::result(...$result)['state']==='uncertain','Missing confirmation must not be automatically retried');
$check(C::result(true,403,'secret response')['state']==='failed','HTTP denial');
$check(!str_contains(json_encode(C::result(true,500,'secret response')),'secret response'),'Raw remote response leaked');
$reject(fn()=>(new C())->send([],"bad\r\nheader"));
$ntfy=$settings;$ntfyNotice='';$ntfyRows=[['order_id'=>42,'order_number'=>'<script>alert(1)</script>','created_at'=>'2026-11-06 12:30:00','state'=>'uncertain','attempts'=>1,'last_error'=>'<b>failure</b>']];
$csrf='fixture';$adminUrl='/admin/';$escape=static fn($s)=>htmlspecialchars((string)$s,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8');
ob_start();require dirname(__DIR__).'/view/admin/settings-notifications.php';$html=ob_get_clean();
foreach(['name="address"','https://ntfy.sh/private-fixture','name="enabled"','name="csrf"','name="confirm_retry"','ntfy-test'] as $part)$check(str_contains($html,$part),'Missing settings control');
$check(!str_contains($html,'<script>alert(1)</script>') && !str_contains($html,'<b>failure</b>'),'Unescaped queue values');
echo "ntfy: safe full URLs, strict settings, order details, Unicode, privacy, delivery responses and UI passed.\n";
